"""Public PT/EN documents; a review draft cannot silently become a final policy."""
import html,json,re
from pathlib import Path
from online_safety import TERMS_TEXT

TERMS_PT='Usa uma alcunha, nunca o nome completo real, contactos ou escola. Não publiques abuso, ódio, conteúdo sexual, ameaças, usurpação de identidade ou spam. Nomes e equipas só ficam públicos após análise. Denuncia ou bloqueia entradas inseguras. Os moderadores podem remover recordes e suspender publicações. Os resultados são auto-reportados. Podes parar a partilha e remover os teus recordes a qualquer momento.'
DETAIL_FIELDS=('legal_basis','provider_practices','children_practices','international_transfers')
SOURCE_LINKS=(
 ('GitHub — Privacy statement','https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement'),
 ('Cloudflare — Privacy policy','https://www.cloudflare.com/privacypolicy/'),
 ('Cloudflare — Data Processing Addendum','https://www.cloudflare.com/cloudflare-customer-dpa/'),
 ('Cloudflare — GDPR','https://www.cloudflare.com/trust-hub/gdpr/'),
 ('Google Play — User Data','https://support.google.com/googleplay/android-developer/answer/10144311?hl=en'),
 ('Google Play — Families','https://support.google.com/googleplay/android-developer/answer/9893335?hl=en'),
)

def load_config(config_path,privacy=True):
    path=Path(config_path)
    if path.stat().st_size>65536:raise ValueError('Public configuration exceeds limit')
    d=json.loads(path.read_text(encoding='utf8'))
    if not isinstance(d,dict):raise ValueError('Public configuration must be an object')
    if not all(isinstance(d.get(k),str) and d[k].strip() for k in ('developer_name','support_email')):raise ValueError('Developer name and support email are required')
    if not re.fullmatch(r'[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+',d['support_email']):raise ValueError('Invalid public email')
    status=d.get('publication_status','draft')  # Missing status must never imply that legal review is complete.
    if status not in ('draft','published'):raise ValueError('Unknown policy status')
    if privacy:
        if not all(isinstance(d.get(k),str) and d[k].strip() for k in ('effective_date',*DETAIL_FIELDS)):raise ValueError('Privacy description fields are incomplete')
        for k in DETAIL_FIELDS:
            if k+'_en' in d and (not isinstance(d[k+'_en'],str) or not d[k+'_en'].strip()):raise ValueError('Invalid English description')
    return dict(d,publication_status=status)

def _p(text):return '<p>'+html.escape(text)+'</p>'
def _heading(text):return '<h2>'+html.escape(text)+'</h2>'

def _privacy(d,en=False):
    detail=lambda k:d.get(k+'_en',d[k]) if en else d[k]
    if en:
        parts=[_p('Scorer World (com.clemir.scorerworld) is a free football career game with an included local names editor. It has no adverts, advertising SDKs or in-app purchases. This policy covers Scorer World and the retained records of earlier Scorer test builds. The separate Free edition is not a Google Play launch product.'),
        _heading('App version compatibility'),_p('At startup, on returning to the app and occasionally while menus are open, Scorer requests a public minimum-version policy from stats.clemir.com. The installed version is compared locally; the request contains no player name, career, usage counters, advertising ID or unique device identifier. Cloudflare processes connection information as described below. This compatibility check is separate from optional usage statistics. A valid policy is cached locally: offline play remains available unless an already known minimum version requires an update. The update button opens the official Google Play listing; the app does not download or install APK files itself.'),
        _heading('Optional usage statistics'),_p('From version code 1030005, I AGREE on the startup notice enables aggregate usage statistics. I DO NOT AGREE closes the game without sending statistics. No statistics are transmitted before agreement. Stop Statistics & Erase Unsent in Help > Settings stops collection and deletes pending counts without affecting play; accepting the startup notice again enables statistics again. Earlier versions 1030000–1030004 required a separate adult PIN choice in Settings. Stop Statistics & Erase Unsent stops future collection and deletes pending counters; it needs no PIN. A request already transmitted cannot be recalled. The nine aggregate numeric counters are app openings and normal closes, new and loaded careers, completed training and matches, goals and save/load failures. Recipient: stats.clemir.com; purpose: improve and maintain the game. No player name, career file, free text, exact event time or device/session identifier is in the counter payload. Cloudflare processes connection data including IP addresses. Local unsent counts expire after seven days; own server totals are combined by UTC receipt day and retained for 90 days. Combined totals cannot be traced back to remove an individual contribution. Delays or uncertain acknowledgments may duplicate events. Earlier test builds used automatic counters; update to the current app.'),
        _heading('Optional public records'),_p('Adult-managed access, community rules and explicit Share precede publication of the chosen player nickname, team, season, matches, goals and edition/country/division. The Season category contains completed-season results; the separately enabled Career category contains cumulative club-career matches and goals, not international totals. Use a nickname, never personal contact or school details. New or changed submissions await moderator review; scores are self-reported. A private random ownership token authorizes uploads/removal; the server stores its hash. Opaque public publisher/record IDs support reports and blocking, but cannot authorize deletion. Records remain until withdrawal or moderation.'),
        _heading('Children and local adult controls'),_p(detail('children_practices')),_p('Adult PINs are stored as salted hashes on the device. Blocked publisher IDs and safety preferences also remain local. An adult can lock public access and queue withdrawal of records. PINs are never published, exported or sent to the server.'),
        _heading('Reports, moderation and removal'),_p('Report/block tools are inside the app. Reports transmit the reporter token, target public publisher ID and a fixed reason; the server keeps the hashed reporter identity, target and reason for up to 30 days with periodic cleanup. Moderators may reject/erase records and suspend publishers. A suspended public ID remains until lifted to prevent re-publication. Stop sharing & remove deletes both Season and Career records and reports associated with the publisher, and is available even when public features are locked. Offline removal is retried while the app runs; keep the app until removal completes. If app data or the ownership credential is lost, contact support without sending secret tokens. Uninstalling does not remove public records.'),
        _heading('Included names editor'),_p('The editor changes club, league and player display names locally. JSON document imports are previewed before applying. Editing does not change match statistics. There is no automatic upload of name packs or career files. Edited team/player names can appear in a public Season or Career record only through the separately enabled record-sharing feature.'),_heading('Local careers, exports and backups'),_p('Careers remain on-device; there is no automatic cloud career upload or email/password account. English is the default; language selection and optional phone-language detection are local. Android app backup is disabled. User-selected career exports contain player names and game progress; keep them private and choose a trusted document provider, which may itself use cloud storage. Exports exclude adult controls, usage counters and online ownership credentials. Only the same edition can import a career. Uninstall removes private local files, not exported documents. Managed server recovery backups contain aggregate counters only, exclude public records/reports/privacy requests/tokens, and expire after seven days.'),
        _heading('Local purchases and feedback'),_p('Career wages, purchases and estate portraits are fictional and stored locally. There are no real payments, user-photo uploads or automatic financial-data transmissions. Feedback opens a draft in your external email app with a subject; you choose whether to send it. No save, logs or attachments are added automatically. If you send email, the developer processes your reply address and message to answer you.'),
        _heading('Transport and Cloudflare'),_p('HTTPS validates certificates. The server is operated by the developer and uses Cloudflare Tunnel/CDN. Our collector suppresses IP, user-agent and raw-request logging. This does not mean the network provider processes no personal data.'),_p(detail('provider_practices')),
        _heading('International processing'),_p(detail('international_transfers')),
        _heading('Legal basis and rights'),_p(detail('legal_basis')),
        _p('Contact goncalo@clemir.com for information, access, correction, erasure, restriction, objection, portability where applicable, or assistance with a child’s privacy. We assess requests and normally respond within one month, with any lawful extension explained. We request only proportionate information needed to establish authority and locate the relevant data. Combined anonymous totals cannot be separated into individual contributions. Email correspondence is used to answer the request and retained only as needed for handling and legal obligations. Do not send passwords, PINs, full career files or administrator/ownership tokens. You may complain to your competent data-protection authority, including the Portuguese CNPD (www.cnpd.pt). There is no sale of personal data, behavioural advertising or automated decision-making with legal or similarly significant effects.'),
        _heading('Changes'),_p('Material changes will be reflected in this policy and, where required, an updated in-app notice before new processing. This policy is effective from the date above.')]

    else:
        parts=[_p('Scorer e Scorer World são apps gratuitas separadas, com carreiras independentes no dispositivo. Não têm anúncios, SDKs de publicidade ou compras dentro da aplicação.'),
        _heading('Contagens automáticas de utilização'),_p('A app 0.6.46 apresenta um aviso detalhado antes do primeiro envio. Envia automaticamente nove contagens: aberturas e fechos normais, carreiras novas e carregadas, treinos e jogos concluídos, golos e falhas de gravação/carregamento. O destinatário é stats.clemir.com e a finalidade é compreender a utilização do jogo. Não existe interruptor de estatísticas na app. Este payload não inclui nomes, carreiras, texto livre, hora exata de eventos ou identificadores de dispositivo/sessão. São eventos, não jogadores únicos. As contagens por enviar expiram localmente após sete dias; o nosso servidor agrega os totais pelo dia UTC de receção e conserva-os durante 90 dias, com limpeza periódica. Atrasos e confirmações de rede incertas podem duplicar contagens. Versões de teste anteriores podem funcionar de outra forma: atualiza para a app atual.'),
        _heading('Recordes públicos opcionais'),_p('O acesso gerido por adulto, as regras da comunidade e a ação explícita Partilhar precedem a publicação do nome do jogador, equipa, época concluída, jogos, golos e edição/país/divisão. Usa uma alcunha, nunca contactos pessoais ou informações da escola. Novas publicações e alterações aguardam análise de um moderador; os resultados são auto-reportados. Um token privado aleatório autoriza envios e remoções; o servidor guarda o seu hash. Identificadores públicos opacos permitem denunciar e bloquear, mas não autorizam a eliminação de dados. Os recordes ficam guardados até retirada ou moderação.'),
        _heading('Menores e controlos locais de adulto'),_p(detail('children_practices')),_p('Os PINs de adulto ficam no dispositivo como hashes com salt. Os identificadores bloqueados e as preferências de segurança também ficam locais. Um adulto pode bloquear o acesso público e colocar os recordes em fila de remoção. Os PINs nunca são publicados, exportados ou enviados para o servidor.'),
        _heading('Denúncias, moderação e remoção'),_p('Há ferramentas de denúncia e bloqueio na app. As denúncias transmitem o token do autor da denúncia, o identificador público visado e um motivo predefinido; o servidor guarda o hash do autor, o alvo e o motivo até 30 dias, com limpeza periódica. O moderador pode rejeitar/apagar recordes ou suspender publicações. O identificador público suspenso mantém-se até a suspensão ser levantada para evitar nova publicação. Parar partilha e remover está disponível mesmo com o acesso público bloqueado. A remoção offline é repetida enquanto a app estiver em execução; mantém a app até confirmar a conclusão. Se perderes os dados ou a credencial de posse, contacta o apoio sem enviar tokens secretos. Desinstalar não remove os recordes públicos.'),
        _heading('Carreiras, exportações e cópias locais'),_p('As carreiras ficam no dispositivo; não há envio automático da carreira para a nuvem nem conta com email/password. O World usa o idioma do telefone localmente. O backup Android da app está desativado. As exportações escolhidas pelo jogador incluem nomes e progresso; mantém-nas privadas e escolhe um fornecedor de documentos de confiança, que poderá usar armazenamento na nuvem. Não são exportados controlos de adulto, contagens ou credenciais de posse online. Só a mesma edição pode importar a carreira. Desinstalar remove ficheiros privados locais, não documentos exportados. As cópias geridas de recuperação do servidor contêm apenas totais agregados, excluem recordes/denúncias/tokens e expiram após sete dias.'),
        _heading('Transporte e Cloudflare'),_p('O HTTPS valida certificados. O servidor é operado pelo responsável e usa Cloudflare Tunnel/CDN. O nosso coletor suprime registos de IP, user agent e pedidos em bruto. Isso não significa que o fornecedor de rede não trate dados pessoais.'),_p(detail('provider_practices')),
        _heading('Tratamento internacional'),_p(detail('international_transfers')),
        _heading('Fundamento e direitos'),_p(detail('legal_basis')),_p('Podes contactar o endereço de privacidade para pedir informação, acesso, correção, eliminação, oposição ou outros direitos aplicáveis. Os pedidos têm de ser avaliados e os requisitos aplicáveis implementados; indicar um email não afasta esses direitos. Totais anónimos já combinados não permitem separar contribuições individuais. Se enviares um email ao apoio, o endereço de resposta e a mensagem são usados para tratar o pedido. Não envies passwords, PINs, carreiras completas nem tokens de administração/posse. Não existe serviço automático de resumos por email. Podes contactar a autoridade de proteção de dados competente, quando aplicável.')]
    return ''.join(parts)

def page(path,config_path):
    if path not in ('/privacy','/terms','/delete'):return 404,b'Not found.'
    try:d=load_config(config_path,privacy=path=='/privacy')
    except (OSError,ValueError,TypeError):return 503,b'Public policy configuration is pending.'
    e=lambda k:html.escape(d[k]);contact='<a href="mailto:'+e('support_email')+'">'+e('support_email')+'</a>'
    title={'/privacy':'Scorer World Privacy Policy','/terms':'Scorer World Community Rules','/delete':'Scorer World Data and Record Removal'}[path]
    draft=path=='/privacy' and d['publication_status']=='draft'
    banner=''
    if draft:
        banner='<aside role="note" class="draft"><strong>DRAFT UNDER REVIEW — TEST BUILD</strong><p>Mandatory analytics for minors and applicable provider practices remain under review. This is not a final policy for a Google Play submission.</p></aside>'
    identity=_p('Responsible developer: '+d['developer_name'])+'<p>Privacy and support: '+contact+'</p>'
    if path=='/privacy':
        identity+=_p(('Draft updated: ' if draft else 'Effective: ')+d['effective_date'])
        body=_privacy(d,True)
        body+='<h2>Official references</h2><ul>'+''.join('<li><a href="'+html.escape(url,quote=True)+'">'+html.escape(name)+'</a></li>' for name,url in SOURCE_LINKS)+'</ul>'
    elif path=='/terms':body=_p(TERMS_TEXT)
    else:
        body=_p('In Scorer World, open Help > Settings or Leaderboard and choose Stop sharing & remove. Keep the app until removal completes. You can remove your public records even when public features are locked. If you lost the app or cannot remove a record, contact the address above with the public name, team, category (Season or Career), season and division. Do not send passwords, adult PINs or administrator/ownership tokens. We assess requests without disclosing another person’s data. Scorer World has no email/password account. Uninstalling does not erase public records. Requests concerning retained records from earlier Scorer test builds can use the same contact.')
    nav='<nav><a href="/privacy">Privacy Policy</a> · <a href="/terms">Community Rules</a> · <a href="/delete">Data and Record Removal</a></nav>'
    status='draft' if draft else 'operational' if path!='/privacy' else 'published'
    doc='<!doctype html><html lang="en" data-publication-status="'+status+'"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+html.escape(title)+'</title>'+('<meta name="robots" content="noindex">' if draft else '')+'<style>body{font:18px system-ui;max-width:900px;margin:28px auto;padding:16px;line-height:1.65;color:#132d37}a{color:#005d66}h1{font-size:1.8em}h2{font-size:1.3em}nav{padding:12px 0}.draft{padding:18px;background:#fff3cc;border:2px solid #a66b00;border-radius:8px}p{overflow-wrap:anywhere}</style><body><h1>'+html.escape(title)+'</h1>'+nav+banner+identity+body+nav+'</body></html>'
    return 200,doc.encode('utf8')
